1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	// Assembles the per-arch entry path and exception vectors into the kernel.
4	//
5	// .S files go through clang (cross-targeted at the kernel triple) and the
6	// resulting .o files are passed straight to the linker via cargo:rustc-link-arg.
7	// We deliberately *avoid* the cc crate's static-library packaging because the
8	// linker's archive member resolution wouldn't pull in `_start` (it's only
9	// referenced via the linker-script `ENTRY` directive, not from any Rust
10	// symbol). Direct .o linkage sidesteps that, and it also dodges the
11	// macOS-ar/ELF-object mismatch entirely.
12	
13	use std::path::PathBuf;
14	use std::process::Command;
15	
16	fn main() {
17	    // Host builds (cargo check / cargo test on macOS or Linux) compile the
18	    // kernel crate as a no-op (main.rs gates every real module on
19	    // `target_os = "none"`). Skip assembly entirely for those — the ELF .o
20	    // files clang would produce here aren't link-compatible with the
21	    // host's mach-o or glibc-flavored ELF and would only break tests.
22	    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
23	    if target_os != "none" {
24	        return;
25	    }
26	
27	    let arch = std::env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH unset");
28	    let out_dir = PathBuf::from(std::env::var_os("OUT_DIR").expect("OUT_DIR unset"));
29	
30	    match arch.as_str() {
31	        "aarch64" => {
32	            let sources = [
33	                "src/arch/aarch64/entry.S",
34	                "src/arch/aarch64/vectors.S",
35	                "src/arch/aarch64/trap.S",
36	                "src/arch/aarch64/interrupt.S",
37	                "src/arch/aarch64/user_stub.S",
38	            ];
39	            for src in &sources {
40	                println!("cargo:rerun-if-changed={src}");
41	                let stem = std::path::Path::new(src)
42	                    .file_stem()
43	                    .unwrap()
44	                    .to_string_lossy();
45	                let obj = out_dir.join(format!("{stem}.o"));
46	                let status = Command::new("clang")
47	                    .args([
48	                        "--target=aarch64-unknown-none",
49	                        "-ffreestanding",
50	                        "-c",
51	                        src,
52	                        "-o",
53	                    ])
54	                    .arg(&obj)
55	                    .status()
56	                    .expect("failed to spawn clang");
57	                if !status.success() {
58	                    panic!("clang failed assembling {src}");
59	                }
60	                println!("cargo:rustc-link-arg={}", obj.display());
61	            }
62	            println!("cargo:rerun-if-changed=src/arch/aarch64/linker.ld");
63	
64	            // Build every boot server as a freestanding EL0 ELF, pack them into
65	            // the MXBI boot-image archive, and emit `BOOT_IMAGE_PATH` for
66	            // `boot_image` to `include_bytes!` (slice 4.2, generalizing the
67	            // slice-3.4 single-VM embed).
68	            build_boot_image(&out_dir);
69	        }
70	        "x86_64" => {
71	            // Phase 8 territory -- nothing to assemble yet.
72	        }
73	        other => panic!("unsupported target arch: {other}"),
74	    }
75	}
76	
77	/// Build every boot server, pack the resulting ELFs into the MXBI boot-image
78	/// archive in `OUT_DIR`, and emit `BOOT_IMAGE_PATH` so `boot_image` can
79	/// `include_bytes!` it (slice 4.2). Generalizes the slice-3.4 single-VM embed.
80	///
81	/// The server list is the single source of truth for which servers boot and at
82	/// which proc number; the proc numbers must match `kernel-shared/src/com.rs`.
83	/// VM is built first so it takes ASID 1 and is enqueued first (its
84	/// `RECEIVE(ANY)` blocks immediately, matching the pre-4.2 boot behavior).
85	fn build_boot_image(out_dir: &std::path::Path) {
86	    let manifest =
87	        PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR unset"));
88	    let workspace = manifest.parent().expect("kernel manifest has no parent");
89	
90	    // Libraries every server links against. Watched once (not per-server) so a
91	    // change re-runs build.rs and re-embeds. Each is watched as a directory so
92	    // cargo covers every submodule recursively — otherwise an edit to e.g. a new
93	    // `minix-ipc` module or DS request number would embed stale ELFs.
94	    for path in [
95	        workspace.join("minix-ipc/src"),
96	        workspace.join("server-rt/src"),
97	        workspace.join("kernel-shared/src"),
98	    ] {
99	        println!("cargo:rerun-if-changed={}", path.display());
100	    }
101	
102	    // (cargo package, crate dir, boot proc number). Proc numbers come from
103	    // `kernel-shared/src/com.rs`; the archive carries them so the loader writes
104	    // the right proc slot. `worker` is packed with proc_nr -1
105	    // (`com::EXEC_ONLY_PROC_NR`): it is not a boot server — the loader skips any
106	    // negative proc_nr — but it is resolvable by name for `SYS_EXEC` (slice 4.7).
107	    let servers: [(&str, std::path::PathBuf, i32); 8] = [
108	        ("minixrs-vm", workspace.join("servers/vm"), 7), // VM_PROC_NR
109	        ("minixrs-ds", workspace.join("servers/ds"), 5), // DS_PROC_NR
110	        ("minixrs-vfs", workspace.join("servers/vfs"), 1), // VFS_PROC_NR
111	        ("minixrs-sched", workspace.join("servers/sched"), 9), // SCHED_PROC_NR
112	        ("minixrs-rs", workspace.join("servers/rs"), 2), // RS_PROC_NR
113	        ("minixrs-pm", workspace.join("servers/pm"), 0), // PM_PROC_NR
114	        ("minixrs-init", workspace.join("userland/init"), 10), // INIT_PROC_NR — PID 1
115	        ("minixrs-worker", workspace.join("userland/worker"), -1), // EXEC_ONLY_PROC_NR
116	    ];
117	
118	    let mut modules: Vec<(i32, String, Vec<u8>)> = Vec::with_capacity(servers.len());
119	    for (crate_name, crate_dir, proc_nr) in &servers {
120	        let elf = build_server(crate_name, crate_dir, workspace, out_dir);
121	        let bytes = std::fs::read(&elf)
122	            .unwrap_or_else(|e| panic!("reading {crate_name} ELF {}: {e}", elf.display()));
123	        let name = crate_name.strip_prefix("minixrs-").unwrap_or(crate_name);
124	        modules.push((*proc_nr, name.to_string(), bytes));
125	    }
126	
127	    let archive = pack_mxbi(&modules);
128	    let archive_path = out_dir.join("boot_image.mxbi");
129	    std::fs::write(&archive_path, &archive).expect("writing boot-image archive");
130	    println!("cargo:rustc-env=BOOT_IMAGE_PATH={}", archive_path.display());
131	}
132	
133	/// Build one server crate for the aarch64 EL0 user target and return the path to
134	/// the produced ELF.
135	///
136	/// We reuse the builtin `aarch64-unknown-none` triple but must NOT inherit the
137	/// kernel's linker script: the workspace `.cargo/config.toml` forces
138	/// `-Tkernel/.../linker.ld` on that triple via `rustflags`. We override it with
139	/// `CARGO_ENCODED_RUSTFLAGS` (highest-precedence; replaces config rustflags
140	/// entirely) pointing at the server's `user.ld`, and isolate each build in its
141	/// own `CARGO_TARGET_DIR` so nesting cargo inside this build script does not
142	/// deadlock on the outer kernel build's target-dir lock.
143	fn build_server(
144	    crate_name: &str,
145	    crate_dir: &std::path::Path,
146	    workspace: &std::path::Path,
147	    out_dir: &std::path::Path,
148	) -> PathBuf {
149	    let user_ld = crate_dir.join("user.ld");
150	    let target_dir = out_dir.join(format!("{crate_name}-target"));
151	
152	    // Rebuild + re-embed whenever this server's sources, linker script, or
153	    // manifest change. `src` is watched as a directory so submodules (e.g.
154	    // `servers/ds/src/registry.rs`) are covered — watching only `main.rs` would
155	    // silently embed a stale ELF after a submodule edit.
156	    for path in [
157	        crate_dir.join("src"),
158	        user_ld.clone(),
159	        crate_dir.join("Cargo.toml"),
160	    ] {
161	        println!("cargo:rerun-if-changed={}", path.display());
162	    }
163	
164	    // `-C link-arg=-T<user.ld>`, encoded with the \x1f separator cargo expects.
165	    let encoded_rustflags = format!("-Clink-arg=-T{}", user_ld.display());
166	
167	    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".into());
168	    let status = Command::new(cargo)
169	        .current_dir(workspace)
170	        .args([
171	            "build",
172	            "-p",
173	            crate_name,
174	            "--target",
175	            "aarch64-unknown-none",
176	            "--release",
177	        ])
178	        .env("CARGO_TARGET_DIR", &target_dir)
179	        .env_remove("RUSTFLAGS")
180	        .env("CARGO_ENCODED_RUSTFLAGS", encoded_rustflags)
181	        .status()
182	        .unwrap_or_else(|e| panic!("failed to spawn cargo for {crate_name}: {e}"));
183	    if !status.success() {
184	        panic!("building {crate_name} (server ELF) failed");
185	    }
186	
187	    let elf = target_dir.join(format!("aarch64-unknown-none/release/{crate_name}"));
188	    assert!(
189	        elf.exists(),
190	        "{crate_name} ELF missing at {}",
191	        elf.display()
192	    );
193	    elf
194	}
195	
196	/// Pack server ELFs into the minix.rs boot-image (MXBI) archive:
197	///
198	/// ```text
199	///   16-byte header: magic "MXBI" (LE u32), version, entry_count, total_size
200	///   entry_count × 32-byte records: { proc_nr:i32, offset:u32, len:u32, name:[u8;20] }
201	///   then the ELF payloads back-to-back, each at its recorded offset
202	/// ```
203	///
204	/// All multi-byte fields are little-endian (build host and aarch64 target are
205	/// both LE); `boot_image::BootImage` parses this with matching `from_le_bytes`.
206	fn pack_mxbi(modules: &[(i32, String, Vec<u8>)]) -> Vec<u8> {
207	    const MAGIC: u32 = 0x4942_584D; // "MXBI" as little-endian bytes M,X,B,I
208	    const VERSION: u32 = 1;
209	    const HDR_LEN: usize = 16;
210	    const REC_LEN: usize = 32;
211	    const NAME_LEN: usize = 20;
212	
213	    let n = modules.len();
214	    let payload_start = HDR_LEN + n * REC_LEN;
215	
216	    // Build the record table, assigning each payload an offset past the table.
217	    let mut offset = payload_start;
218	    let mut records = Vec::with_capacity(n * REC_LEN);
219	    for (proc_nr, name, bytes) in modules {
220	        let name_bytes = name.as_bytes();
221	        assert!(
222	            name_bytes.len() < NAME_LEN,
223	            "server name {name:?} too long for MXBI {NAME_LEN}-byte name field"
224	        );
225	        records.extend_from_slice(&proc_nr.to_le_bytes());
226	        records.extend_from_slice(&(offset as u32).to_le_bytes());
227	        records.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
228	        let mut name_field = [0u8; NAME_LEN];
229	        name_field[..name_bytes.len()].copy_from_slice(name_bytes);
230	        records.extend_from_slice(&name_field);
231	        offset += bytes.len();
232	    }
233	    let total_size = offset;
234	
235	    let mut archive = Vec::with_capacity(total_size);
236	    archive.extend_from_slice(&MAGIC.to_le_bytes());
237	    archive.extend_from_slice(&VERSION.to_le_bytes());
238	    archive.extend_from_slice(&(n as u32).to_le_bytes());
239	    archive.extend_from_slice(&(total_size as u32).to_le_bytes());
240	    archive.extend_from_slice(&records);
241	    for (_, _, bytes) in modules {
242	        archive.extend_from_slice(bytes);
243	    }
244	    assert_eq!(archive.len(), total_size, "MXBI archive size mismatch");
245	    archive
246	}
